insert into public.reg_pack (id, version, published_at, notes) values
  ('washington-2026-09-02', 3, '2026-09-02T12:00:00Z', 'Washington ocean Marine Areas 1-4 (WDFW news release March 5, 2026) — v2 deepens with the inside-waters doctrine (no rockfish 6-13, barbless hooks 5-13), Puget Sound halibut windows (1/day, 6/yr, catch record card), the North Coast 20-fathom retention list, the C-shaped yelloweye conservation area, wolf-eel closure, and the five-additional-flatfish rule. v3 lands the Puget Sound pamphlet tables for Marine Areas 9, 10 and 13 verbatim (2026-27 book, updated June 18 2026): 15 bottomfish daily, >120ft fishing prohibited, descending device required, lingcod May 1-Jun 15 slot 26-36 in (spear May 21-Jun 15, hook-and-line from May 1), cabezon May 1-Nov 30 @18 in @1, rockfish closed, cod/pollock/hake/wolf-eel closed, salmon headline windows as notes. Crab/shrimp tables still pending.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;
